xt":"Yeni sezon editöryel","font":"accent"}},{"type":"heading","settings":{"tag":"h2","text":"Her sabah giyinmek bir sanattır."}},{"type":"button","settings":{"text":"Koleksiyona git →","link_url":"/collections","style":"outline"}}]},{"type":"featured_products","settings":{"title":"Bu Sezonun Favorileri","subtitle":"Editörlerimizin seçimleri","columns":4,"products_count":8,"card_style":"boutique","image_ratio":"portrait","hover_image":true,"wishlist":true,"quick_view":true,"show_add_to_cart":true,"badges":true},"blocks":[]},{"type":"lookbook","settings":{"title":"Sonbahar Lookbook"},"blocks":[]},{"type":"featured_products","settings":{"title":"Yeni Gelenler","layout":"scroll","columns":4,"products_count":10,"card_style":"boutique","image_ratio":"portrait","hover_image":true},"blocks":[]},{"type":"logo_strip","settings":{"title":"Markalar","items":"ZARA\nMANGO\nLC WAIKIKI\nKOTON\nBOYNER\nDEFACTO\nH&M\nBERSHKA","grayscale":true},"blocks":[]},{"type":"trust_badges","settings":{"items":"🚚|Ücretsiz Kargo|299₺ üzeri\n🔄|30 Gün İade|Koşulsuz iade\n🔒|Güvenli Ödeme|3D Secure\n💬|Destek|Her gün yanınızda"},"blocks":[]},{"type":"testimonials","settings":{"title":"Müşteri Yorumları"},"blocks":[]},{"type":"instagram_grid","settings":{"title":"@couture_tr''yi takip edin","columns":3},"blocks":[]},{"type":"newsletter","settings":{"title":"İlk alışverişte %10 indirim","subtitle":"Spam yok. İstediğinizde çıkın."},"blocks":[]}]}}'::jsonb,true);
insert into v2_theme_templates(name,slug,description,category,features,is_official,is_featured,is_published,structure_json,preview_url) select 'Couture','couture','Giyim, moda ve butikler için sıcak kırık beyaz, bordo vurgulu premium tema.','fashion','["İkiye bölünmüş editöryel hero ve yavaş yakınlaşma", "Mobilde yana kaydırılan kategoriler", "İkinci görselli, sepete ekleyen ürün kartları", "Masonry lookbook ve yeni gelenler kaydırıcısı"]'::jsonb,true,true,true,structure,'/demo/couture' from v2_theme_presets where name='Couture' limit 1 on conflict (slug) do nothing;